"""A tiny conda channel, generated by the driver and served at `/test-channel/`.

Tests installing packages from a self-hosted channel (a static file server,
e.g. GitHub Pages next to the docs): `tests/async/test_channel.py` installs
`pyjs-test-channel-py` with the npm package's `installPackages`. The channel has
the layout rattler-build writes to its output dir:

    noarch/repodata.json
    noarch/pyjs-test-channel-py-1.0.0-py_0.tar.bz2        noarch: python
    emscripten-wasm32/repodata.json
    emscripten-wasm32/pyjs-test-channel-arch-1.0.0-0.tar.bz2   (arch package)
    emscripten-wasm64/...

The noarch package (a python module) depends on the arch package (a data file
naming its arch), like `pyb2d3-sandbox` on `pyb2d3`. A fake `tabulate` 0.0.1
(conda-forge has 0.9.x) tests that the self-hosted channel has priority (a CI
build of a package must win over the published one).
"""

import hashlib
import io
import json
import tarfile

PREFIX = "/test-channel"
VERSION = "1.0.0"
NOARCH_NAME = "pyjs-test-channel-py"
ARCH_NAME = "pyjs-test-channel-arch"
ARCHS = ["wasm32", "wasm64"]
# also on conda-forge (noarch, 0.9.x), not in the test envs: tests the priority
# of the self-hosted channel over the default ones
SHADOW_NAME = "tabulate"
SHADOW_VERSION = "0.0.1"

PY_MODULE = '''\
"""installed from the self-hosted test channel"""
import os
import sys

VALUE = 42


def arch_of_dependency():
    """the arch written into the arch package (a dependency of this package)"""
    with open(os.path.join(sys.prefix, "share", "pyjs_test_channel", "arch.txt")) as f:
        return f.read().strip()
'''


def _tar_bz2(files):
    """a .tar.bz2 conda package from {path: bytes}"""
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:bz2") as tar:
        for path, data in sorted(files.items()):
            info = tarfile.TarInfo(path)
            info.size = len(data)
            info.mode = 0o644
            tar.addfile(info, io.BytesIO(data))
    return buf.getvalue()


def _package(index, payload):
    """conda package bytes: payload files + info/index.json + info/paths.json"""
    paths = {
        "paths_version": 1,
        "paths": [
            {"_path": p, "path_type": "hardlink", "sha256": hashlib.sha256(d).hexdigest(), "size_in_bytes": len(d)}
            for p, d in sorted(payload.items())
        ],
    }
    files = dict(payload)
    files["info/index.json"] = json.dumps(index).encode()
    files["info/paths.json"] = json.dumps(paths).encode()
    files["info/files"] = "".join(f"{p}\n" for p in sorted(payload)).encode()
    return _tar_bz2(files)


def _repodata(subdir, packages):
    """repodata.json of a subdir from {filename: (index, bytes)}"""
    entries = {}
    for filename, (index, data) in packages.items():
        entries[filename] = {
            **index,
            "md5": hashlib.md5(data).hexdigest(),
            "sha256": hashlib.sha256(data).hexdigest(),
            "size": len(data),
        }
    return json.dumps({"info": {"subdir": subdir}, "packages": entries, "packages.conda": {}}).encode()


def build():
    """{url path: bytes} of the whole channel"""
    out = {}

    noarch_index = {
        "name": NOARCH_NAME,
        "version": VERSION,
        "build": "py_0",
        "build_number": 0,
        "depends": [ARCH_NAME, "python"],
        "noarch": "python",
        "subdir": "noarch",
        "license": "BSD-3-Clause",
        "timestamp": 0,
    }
    noarch_file = f"{NOARCH_NAME}-{VERSION}-py_0.tar.bz2"
    noarch_data = _package(noarch_index, {"site-packages/pyjs_test_channel/__init__.py": PY_MODULE.encode()})
    out[f"{PREFIX}/noarch/{noarch_file}"] = noarch_data

    # a package conda-forge also has, with a much higher version: the
    # self-hosted channel must win (channel priority), not the version
    shadow_index = {
        "name": SHADOW_NAME,
        "version": SHADOW_VERSION,
        "build": "py_0",
        "build_number": 0,
        "depends": ["python"],
        "noarch": "python",
        "subdir": "noarch",
        "license": "BSD-3-Clause",
        "timestamp": 0,
    }
    shadow_file = f"{SHADOW_NAME}-{SHADOW_VERSION}-py_0.tar.bz2"
    shadow_data = _package(
        shadow_index, {f"site-packages/{SHADOW_NAME}.py": b"FROM_TEST_CHANNEL = True\n"}
    )
    out[f"{PREFIX}/noarch/{shadow_file}"] = shadow_data
    out[f"{PREFIX}/noarch/repodata.json"] = _repodata(
        "noarch", {noarch_file: (noarch_index, noarch_data), shadow_file: (shadow_index, shadow_data)}
    )

    for arch in ARCHS:
        subdir = f"emscripten-{arch}"
        index = {
            "name": ARCH_NAME,
            "version": VERSION,
            "build": "0",
            "build_number": 0,
            "depends": [],
            "subdir": subdir,
            "license": "BSD-3-Clause",
            "timestamp": 0,
        }
        filename = f"{ARCH_NAME}-{VERSION}-0.tar.bz2"
        data = _package(index, {"share/pyjs_test_channel/arch.txt": arch.encode()})
        out[f"{PREFIX}/{subdir}/{filename}"] = data
        out[f"{PREFIX}/{subdir}/repodata.json"] = _repodata(subdir, {filename: (index, data)})
    return out
